* Stimulus
Vclk clock 0 PULSE(0 1.8 0 100p 100p 4.9n 10n)
Venable enable 0 PULSE(0 1.8 50n 100p 100p 10u 20u)
Vstore Store 0 0
Vxfer Xfer 0 0

.control
tran 1n 500n uic

* Measure mean bitline voltage
meas tran mean_vbit avg v(vbit) from=100n to=500n

* Measure bitline ripple
meas tran max_vbit max v(vbit) from=100n to=500n
meas tran min_vbit min v(vbit) from=100n to=500n
let vbit_ripple = max_vbit - min_vbit
print vbit_ripple

* Measure average power
meas tran mean_current avg i(VDD) from=100n to=500n
let power = -mean_current * 1.8
print power

quit
.endc

